CREATE TABLE public.leads (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, name TEXT, email TEXT NOT NULL, company TEXT, message TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.leads TO authenticated; GRANT ALL ON public.leads TO service_role; ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage own leads" ON public.leads FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);